const raw = $('On Handoff Request').item.json;
const j = { ...raw, ...(raw.triage || {}) };
const rec = $('Load email_events State').first().json || {};
const ef = rec.fields || rec;
const existingDraftId = String(ef.draft_id || '');
const existingTaskId = String(ef.task_id || '');
const reviewRequired = !!j.review_required;
const accepted = !reviewRequired;
const createDraft = accepted && !!j.needs_reply && !existingDraftId;
const createTask = accepted && !!j.needs_task && !existingTaskId;
const urgentConfig = { importance: 'high', categories: ['client_request', 'billing'] };
const sendAlert = accepted && j.importance === urgentConfig.importance && urgentConfig.categories.includes(j.category);
return [{ json: {
  ...j,
  existing_draft_id: existingDraftId,
  existing_task_id: existingTaskId,
  create_draft: createDraft,
  create_task: createTask,
  send_alert: sendAlert,
  task_idempotency_key: j.message_id ? 'msg:' + j.message_id : j.idempotency_key
}}];

const plan = $('Prepare Handoff Plan').item.json;
const optionalFirstJson = (name) => {
  try { return $(name).first().json || {}; }
  catch { return {}; }
};
const draft = optionalFirstJson('Create Gmail Draft');
const task = optionalFirstJson('Create Asana Task');
const alert = optionalFirstJson('Send Urgent Alert');
const draftId = String(draft.id || draft.draftId || draft.data?.id || plan.existing_draft_id || '');
const draftError = plan.create_draft && !draftId ? String(draft.error?.message || draft.error || 'gmail_draft_create_failed') : '';
const taskId = String(task.gid || task.id || task.data?.gid || task.data?.id || plan.existing_task_id || '');
const taskError = plan.create_task && !taskId ? String(task.error?.message || task.error || 'asana_create_failed') : '';
const alertId = String(alert.id || alert.messageId || alert.threadId || '');
const alertError = plan.send_alert && !alertId ? String(alert.error?.message || alert.error || 'urgent_alert_send_failed') : '';
const errorCode = taskError || draftError || alertError;
const failedStage = taskError ? 'asana_task_create' : (draftError ? 'gmail_draft_create' : (alertError ? 'urgent_alert_send' : ''));
return [{ json: {
  correlation_id: plan.correlation_id,
  message_id: plan.message_id,
  email_event_id: plan.email_event_id,
  draft_id: draftId,
  draft_error: draftError,
  task_id: taskId,
  task_status: taskError ? 'failed' : (taskId ? 'synced' : 'not_applicable'),
  task_error_code: taskError,
  alert_sent: !!alertId,
  alert_error: alertError,
  review_required: plan.review_required,
  review_queue_id: plan.review_queue_id || '',
  handoff_failed: !!errorCode,
  error_code: errorCode,
  failed_stage: failedStage
} }];

const c = $('Capture Handoff Results').item.json;
let finalStatus = 'handoff_complete';
if (c.task_error_code) finalStatus = 'task_failed_other_actions_preserved';
else if (c.draft_error) finalStatus = 'draft_failed_other_actions_preserved';
else if (c.alert_error) finalStatus = 'alert_failed_other_actions_preserved';
return [{ json: {
  correlation_id: c.correlation_id,
  message_id: c.message_id,
  email_event_id: c.email_event_id,
  draft_id: c.draft_id,
  draft_error: c.draft_error,
  task_id: c.task_id,
  task_status: c.task_status,
  task_error_code: c.task_error_code,
  alert_sent: c.alert_sent,
  alert_error: c.alert_error,
  review_required: c.review_required,
  review_queue_id: c.review_queue_id,
  final_status: finalStatus
}}];
